class Solution:
    def longestRepeat(self, s: str) -> int:
        n, best = len(s), 0
        for d in range(1, n):
            run = 0
            for i in range(n - d):
                run = run + 1 if s[i] == s[i + d] else 0
                best = max(best, run)
        return best

