class Solution {
    public int longestRepeat(String s) {
        int n = s.length(), best = 0;
        for (int d = 1; d < n; d++) {
            int run = 0;
            for (int i = 0; i + d < n; i++) {
                run = s.charAt(i) == s.charAt(i + d) ? run + 1 : 0;
                best = Math.max(best, run);
            }
        }
        return best;
    }
}

