class Solution:
    def longestRepeat(self, s: str) -> int:
        M1, M2, B, n = 1_000_000_007, 1_000_000_009, 131, len(s)
        pre1, pre2, pw1, pw2 = [0] * (n + 1), [0] * (n + 1), [1] * (n + 1), [1] * (n + 1)
        for i, c in enumerate(s):
            pre1[i + 1], pre2[i + 1] = (pre1[i] * B + ord(c)) % M1, (pre2[i] * B + ord(c)) % M2
            pw1[i + 1], pw2[i + 1] = pw1[i] * B % M1, pw2[i] * B % M2

        def repeats(L):
            seen = set()
            for i in range(n - L + 1):
                key = ((pre1[i + L] - pre1[i] * pw1[L]) % M1, (pre2[i + L] - pre2[i] * pw2[L]) % M2)
                if key in seen:
                    return True
                seen.add(key)
            return False

        lo, hi = 0, n - 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if repeats(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

