class Solution {
    static final long M1 = 1_000_000_007L, M2 = 1_000_000_009L, B = 131;
    long[] pre1, pre2, pw1, pw2;

    private boolean repeats(int n, int L) {
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i + L <= n; i++) {
            long a = (pre1[i + L] - pre1[i] * pw1[L] % M1 + M1) % M1;
            long b = (pre2[i + L] - pre2[i] * pw2[L] % M2 + M2) % M2;
            if (!seen.add(a << 32 | b)) return true;
        }
        return false;
    }

    public int longestRepeat(String s) {
        int n = s.length();
        pre1 = new long[n + 1]; pre2 = new long[n + 1]; pw1 = new long[n + 1]; pw2 = new long[n + 1];
        pw1[0] = pw2[0] = 1;
        for (int i = 0; i < n; i++) {
            pre1[i + 1] = (pre1[i] * B + s.charAt(i)) % M1;
            pre2[i + 1] = (pre2[i] * B + s.charAt(i)) % M2;
            pw1[i + 1] = pw1[i] * B % M1;
            pw2[i + 1] = pw2[i] * B % M2;
        }
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (repeats(n, mid)) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

