#define M1 1000000007LL
#define M2 1000000009LL
#define BASE 131LL

static int by_key(const void* x, const void* y) {
    unsigned long long a = *(const unsigned long long*) x, b = *(const unsigned long long*) y;
    return a < b ? -1 : a > b;
}

static bool repeats(long long* pre1, long long* pre2, long long* pw1, long long* pw2, int n, int L, unsigned long long* keys) {
    int count = n - L + 1;
    for (int i = 0; i < count; i++) {
        long long a = (pre1[i + L] - pre1[i] * pw1[L] % M1 + M1) % M1;
        long long b = (pre2[i + L] - pre2[i] * pw2[L] % M2 + M2) % M2;
        keys[i] = (unsigned long long) a << 32 | b;
    }
    qsort(keys, count, sizeof(unsigned long long), by_key);
    for (int i = 1; i < count; i++) if (keys[i] == keys[i - 1]) return true;
    return false;
}

int longestRepeat(char* s) {
    int n = strlen(s);
    long long *pre1 = calloc(n + 1, sizeof(long long)), *pre2 = calloc(n + 1, sizeof(long long));
    long long *pw1 = malloc((n + 1) * sizeof(long long)), *pw2 = malloc((n + 1) * sizeof(long long));
    unsigned long long* keys = malloc((n + 1) * sizeof(unsigned long long));
    pw1[0] = pw2[0] = 1;
    for (int i = 0; i < n; i++) {
        pre1[i + 1] = (pre1[i] * BASE + s[i]) % M1;
        pre2[i + 1] = (pre2[i] * BASE + s[i]) % M2;
        pw1[i + 1] = pw1[i] * BASE % M1;
        pw2[i + 1] = pw2[i] * BASE % M2;
    }
    int lo = 0, hi = n - 1;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (repeats(pre1, pre2, pw1, pw2, n, mid, keys)) lo = mid; else hi = mid - 1;
    }
    free(pre1); free(pre2); free(pw1); free(pw2); free(keys);
    return lo;
}
